// Schema: rules per field. Coerce + normalize first, THEN check.
const schema = {
  email: (v) => {
    const s = String(v ?? "").trim().toLowerCase();          // normalize
    if (!s) return "email required";
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)) return "invalid email";
    return null;                                             // null = valid
  },
  age: (v) => {
    const n = Number(v);                                     // coerce (FormData is a string)
    if (!Number.isInteger(n)) return "age must be a whole number";
    if (n < 13) return "must be 13+";
    return null;
  },
};
function validate(input, schema) {
  const errors = {};
  for (const field in schema) { const msg = schema[field](input[field]); if (msg) errors[field] = msg; }
  return { valid: Object.keys(errors).length === 0, errors };
}

