async function optimisticMutate(state, change, serverCall) {
  const snapshot = state;                     // 1. SNAPSHOT before touching anything
  let ui = { ...state, ...change };           // 2. APPLY optimistically (show instantly)
  try {
    const confirmed = await serverCall();     // fire the mutation
    ui = { ...ui, ...confirmed };             // 3a. RECONCILE with authoritative value
    return { ui, status: "confirmed" };
  } catch (e) {
    return { ui: snapshot, status: "rolled-back" };  // 3b. ROLL BACK to the snapshot
  }
}

